<?php
header('Content-Type: application/json');require_once __DIR__.'/../config/response.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../config/audit.php';require_once __DIR__.'/../auth/auth_required.php';require_once __DIR__.'/../auth/role_helper.php';require_once __DIR__.'/review_service.php';
try{if($_SERVER['REQUEST_METHOD']!=='POST')jsonResponse(['success'=>false,'message'=>'Method not allowed'],405);$auth=requireAuth();$uid=authTenantId($auth);$actorId=authActorId($auth);$d=json_decode(file_get_contents('php://input'),true)?:[];$type=strtoupper(trim((string)($d['entity_type']??'')));$entityId=(int)($d['entity_id']??0);$action=strtoupper(trim((string)($d['action']??'NOTE')));$note=trim((string)($d['note']??''));if(!in_array($type,['VAT_PERIOD','ACCOUNTING_PERIOD','CONTRIBUTION_PERIOD','EMPLOYER_DECLARATION','FISCAL_RECONCILIATION','TAX_SCHEDULE_ENTRY','FILING_ARCHIVE'],true)||$entityId<=0||!in_array($action,['NOTE','REQUEST_CHANGES','APPROVE','REJECT'],true)||$note===''||mb_strlen($note)>2000)throw new Exception('Entity, action, and review note are required');$c=db();requirePermission($c,$uid,'reports.view');$role=currentUserRole($c,$uid);$c->begin_transaction();if(!reviewEntityExists($c,$uid,$type,$entityId))throw new Exception('Reviewed entity was not found');$s=$c->prepare('SELECT event_hash FROM erp_accountant_review_events WHERE user_id=? AND entity_type=? AND entity_id=? ORDER BY id DESC LIMIT 1 FOR UPDATE');$s->bind_param('isi',$uid,$type,$entityId);$s->execute();$previous=$s->get_result()->fetch_assoc()['event_hash']??null;$s->close();$hash=reviewEventHash($uid,$type,$entityId,$action,$note,$actorId,$role,$previous);$s=$c->prepare('INSERT INTO erp_accountant_review_events(user_id,entity_type,entity_id,action,note,actor_id,actor_role,previous_event_hash,event_hash) VALUES(?,?,?,?,?,?,?,?,?)');$s->bind_param('isississs',$uid,$type,$entityId,$action,$note,$actorId,$role,$previous,$hash);$s->execute();$id=(int)$s->insert_id;$s->close();auditLog($c,$uid,$actorId,'ACCOUNTANT_REVIEW.'.$action,$type,$entityId,null,['review_event_id'=>$id,'note'=>$note,'actor_role'=>$role,'event_hash'=>$hash]);$c->commit();jsonResponse(['success'=>true,'id'=>$id,'event_hash'=>$hash,'previous_event_hash'=>$previous]);
}catch(Throwable $e){if(isset($c))try{$c->rollback();}catch(Throwable $ignored){}jsonResponse(['success'=>false,'message'=>$e->getMessage()],400);}
